// Actions-only real authenticated HTTP strict manual position requests/privacy.
#[tokio::test]
async fn manual_read_status_http_routes_are_authenticated_and_no_caller_uid_box_token_or_bool_grants(){
 let state=build_test_router().await.expect("Actions private bus required; no skip");let served=serve(state.router.clone()).await;let base="/api/non-3gpp/accounts/app-account-0123456789abcdef0123456789abcdef";
 for(method,path)in[(reqwest::Method::GET,format!("{base}/im-read-status-targets?expected_revision=1")),(reqwest::Method::GET,format!("{base}/im-read-status-actions?limit=16")),(reqwest::Method::POST,format!("{base}/im-read-status-targets/1/set"))]{let(status,_,body)=account_request(&served,method,&path,None,None).await;assert_eq!(status,StatusCode::UNAUTHORIZED);no_secrets(&body);}
 let cookie=authenticate(&served).await;for key in ["uid","box_id","token","reply","span_hash","scope_epoch","confirmed"]{let mut data=serde_json::json!({"expected_revision":1,"expected_index":"7","nonce":"a".repeat(32),"consent":true});data[key]=serde_json::json!("fixture-private");let(status,headers,body)=account_request(&served,reqwest::Method::POST,&format!("{base}/im-read-status-targets/1/set"),Some(data),Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_store(&headers);no_secrets(&body);}
}
#[tokio::test]
async fn manual_read_status_http_stored_config_or_received_row_is_not_live_original_target_permission(){
 let state=build_test_router().await.expect("Actions private bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");let(status,_,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":im_runtime_config_json(&cert.root)})),Some(&cookie)).await;assert_eq!(status,StatusCode::CREATED);let line=created_line(&body);
 for(revision,consent,want)in[(1,false,StatusCode::FORBIDDEN),(2,true,StatusCode::CONFLICT),(1,true,StatusCode::SERVICE_UNAVAILABLE)]{let(status,headers,body)=account_request(&served,reqwest::Method::POST,&format!("/api/non-3gpp/accounts/{line}/im-read-status-targets/1/set"),Some(serde_json::json!({"expected_revision":revision,"expected_index":"7","nonce":"a".repeat(32),"consent":consent})),Some(&cookie)).await;assert_eq!(status,want);no_store(&headers);no_secrets(&body);}let v=state.app.app_accounts.get(&line,100).await.unwrap();assert!(v.im_read_status_supported.is_none());assert_eq!(v.phase,"stopped");assert!(!v.incoming_message_ready&&!v.incoming_call_ready&&!v.outbound_authorized);
}
#[tokio::test]
async fn manual_read_status_http_index_is_only_exact_target_revision_not_a_wire_value_or_overflow_cast(){
 let state=build_test_router().await.expect("Actions private bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let path="/api/non-3gpp/accounts/app-account-0123456789abcdef0123456789abcdef/im-read-status-targets";
 for index in ["-1","01","9223372036854775808"]{let(status,headers,body)=account_request(&served,reqwest::Method::POST,&format!("{path}/1/set"),Some(serde_json::json!({"expected_revision":1,"expected_index":index,"nonce":"a".repeat(32),"consent":true})),Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_store(&headers);no_secrets(&body);}for id in ["0","01","-1"]{let(status,headers,body)=account_request(&served,reqwest::Method::POST,&format!("{path}/{id}/set"),Some(serde_json::json!({"expected_revision":1,"expected_index":"7","nonce":"a".repeat(32),"consent":true})),Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_store(&headers);no_secrets(&body);}
}
